-- Every table enforces immutable=True independently of the Python adapter.
CREATE OR REPLACE FUNCTION ops.protect_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.immutable THEN RAISE EXCEPTION 'immutable record: %', OLD.storage_key; END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER immutable_record BEFORE UPDATE OR DELETE ON ingest.source_items FOR EACH ROW EXECUTE FUNCTION ops.protect_immutable();
CREATE TRIGGER immutable_record BEFORE UPDATE OR DELETE ON evt.events FOR EACH ROW EXECUTE FUNCTION ops.protect_immutable();
