ALTER TABLE ingest.source_items ADD CONSTRAINT valid_published_prec CHECK ("published_prec" IN ('EXACT', 'BUCKET', 'COLLECTION_ONLY'));
ALTER TABLE ingest.source_items ADD CONSTRAINT valid_relevance_decision CHECK ("relevance_decision" IN ('ALWAYS', 'SEND', 'SKIP'));
ALTER TABLE ingest.source_items ADD CONSTRAINT valid_route_decision CHECK ("route_decision" IN ('NEW_SESSION', 'ADDED'));
ALTER TABLE evt.events ADD CONSTRAINT valid_freshness CHECK ("freshness" IN ('FRESH', 'NORMAL', 'MEDIUM', 'POOR', 'OLD', 'STALE'));
ALTER TABLE evt.state_changes ADD CONSTRAINT valid_ladder CHECK ("ladder" IN ('EVENT', 'INTEGRATION'));
ALTER TABLE mkt.funding_obs ADD CONSTRAINT valid_kind CHECK ("kind" IN ('SETTLED', 'CURRENT_ESTIMATE'));
ALTER TABLE mkt.liq_obs ADD CONSTRAINT valid_side CHECK ("side" IN ('LONG_LIQ', 'SHORT_LIQ'));
ALTER TABLE mkt.liq_obs ADD CONSTRAINT valid_coverage CHECK ("coverage" IN ('COMPLETE', 'SAMPLED', 'UNKNOWN'));
ALTER TABLE ana.calls ADD CONSTRAINT valid_status CHECK ("status" IN ('OPEN', 'CLOSED'));
ALTER TABLE ana.calls ADD CONSTRAINT valid_closed_by CHECK ("closed_by" IN ('EXIT', 'EXPIRED'));
ALTER TABLE out.alerts ADD CONSTRAINT valid_kind CHECK ("kind" IN ('PARTIAL', 'FULL', 'UPDATE'));
ALTER TABLE out.deliveries ADD CONSTRAINT valid_status CHECK ("status" IN ('GENERATED', 'SENT', 'FAILED'));
ALTER TABLE ops.agent_sessions ADD CONSTRAINT valid_status CHECK ("status" IN ('OPEN', 'ENDED', 'FAILED'));
ALTER TABLE ops.tool_calls ADD CONSTRAINT valid_status CHECK ("status" IN ('PENDING', 'DONE', 'REFUSED', 'ERROR'));
